export const MONUMENTS = JSON.parse("[{\"id\":\"n5640367795\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. Ф. Писемскому\",\"x\":-2275.6,\"z\":951.7,\"subject\":\"Q470371\",\"inscription\":\"В этом доме с 1858 г. по 1863 г. жил Алексей Феофилактович Писемский. Здесь он написал драму «Горькая судьбина»\"},{\"id\":\"n12201849198\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2256.3,\"z\":975.6,\"inscription\":\"В этом здании 16 мая 1911 года был создан Российский Олимпийский комитет\"},{\"id\":\"n3806778308\",\"kind\":\"memorial\",\"sub\":\"war_memorial\",\"name\":\"ЛИИЖТовцам, павшим в боях за Родину\",\"x\":-1982.2,\"z\":962.5},{\"id\":\"n3806778311\",\"kind\":\"memorial\",\"sub\":\"stele\",\"name\":\"Их было 1423\",\"x\":-1982.4,\"z\":920.4,\"material\":\"stone\"},{\"id\":\"n6218437546\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Я. М. Гаккелю\",\"x\":-1894.4,\"z\":951.5,\"subject\":\"Q4132128\",\"inscription\":\"Здесь работал создатель первых русских самолётов и тепловозов Яков Модестович Гаккель\"},{\"id\":\"n6218437547\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. О. Графтио\",\"x\":-1894.7,\"z\":941.5,\"subject\":\"Q1284495\",\"inscription\":\"Здесь учился академик Графтио Генрих Осипович, видный учёный, энергетик, строитель первенца ГОЭЛРО Волховской ГЭС\"},{\"id\":\"n6218437548\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1894.9,\"z\":932.9,\"subject\":\"Q4360230\",\"inscription\":\"До этой черты доходила вода во время наводнения 7 ноября 1824 года\"},{\"id\":\"n8952171657\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Е. Ю. Учителю\",\"x\":-3045.2,\"z\":945.9,\"subject\":\"Q13218090\",\"inscription\":\"Ефим Юльевич Учитель, кинорежиссер, Народный артист СССР работал с 1935 по 1988 год на Ленинградской студии документальных фильмов\"},{\"id\":\"n8980831248\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. А. Тырсе\",\"x\":-2940.1,\"z\":963.1,\"subject\":\"Q6690711\",\"inscription\":\"В этом доме жил и работал с 1919 по 1942 г. Николай Андреевич Тырса, выдающийся художник и педагог\"},{\"id\":\"n10240871805\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2952.9,\"z\":935.3,\"inscription\":\"В этом доме с 1808 по 1958 год жили представители семей Бенуа, Лансере, Серебряковых, давших миру выдающихся архитекторов, художников, скульпторов и историков искусства\"},{\"id\":\"n8980845364\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Училищу корабельной архитектуры\",\"x\":-2774.8,\"z\":961,\"inscription\":\"Здесь в 1798-1816 годах размещалось первое в мире Училище корабельной архитектуры\"},{\"id\":\"n5646163787\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-1450.4,\"z\":935,\"subject\":\"Q1394\",\"inscription\":\"В этом доме в 1906 году находилась легальная большевистская типография товарищества \\\"Дело\\\". Здесь печатались большевистские газеты \\\"Волна\\\", \\\"Вперед\\\", \\\"Эхо\\\" и \\\"Новая волна\\\". В. И. Ленин неоднократно бывал здесь как редактор этих газет.\"},{\"id\":\"n7143491436\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Язепс Витолс\",\"x\":-1228.2,\"z\":960.6,\"subject\":\"Q553252\",\"inscription\":\"В этом доме с 1895 по 1918 год жил и работал профессор Петербургской консерватории, основоположник латышской классической музыки Язепс Витолс. 1988. Витолс 1863–1948\"},{\"id\":\"n10030114204\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Типографии товарищества «Дело»\",\"x\":-1454,\"z\":938,\"inscription\":\"Дом, где в 1906 г. помещалась типография товарищества «Дело», печатавшая газеты «Волна», «Вперёд», «Новая Волна», «Эхо».\"}]");
